window.kbPageData["views/entry/k-89c1d03096d04b0b"] = {"key":"entry/k-89c1d03096d04b0b","state":{"route":"entry/k-89c1d03096d04b0b"},"node":{"id":"k-89c1d03096d04b0b","mode":"k","title":"全国统一大市场建设中的竞争治理","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["推进全国统一大市场建设","统一大市场中的价格竞争治理"],"qs":["政治理论必刷100题#16","政治理论必刷100题#36"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["market"],"主类":["制度与规则"],"出处性质":["专项题干","专项题解析","机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"全国统一大市场建设中的竞争治理，旨在维护公平有序的市场竞争。2025年《政府工作报告》提出综合整治“内卷式”竞争，2025年7月1日中央财经委员会第六次会议提出依法依规治理企业低价无序竞争。","review":{"title":"全国统一大市场建设中的竞争治理","type":"制度与规则","definition":"全国统一大市场建设中的竞争治理，旨在维护公平有序的市场竞争。2025年《政府工作报告》提出综合整治“内卷式”竞争，2025年7月1日中央财经委员会第六次会议提出依法依规治理企业低价无序竞争。","explanation":"《政府工作报告》把综合整治“内卷式”竞争与破除地方保护和市场分割、打通市场准入退出和要素配置堵点一并部署。中央财经委员会第六次会议把治理企业低价无序竞争与引导企业提升产品品质、推动落后产能有序退出一并部署，其中“无序”限定了低价竞争治理的对象。","basis":"据关联原题及所列出处编释。","references":[{"source":"market2","location":"治理企业低价无序竞争"}],"related":["k-0a6da28c772630a4"],"domain":"经济","examFocus":{"政治理论必刷100题#16":"对照全国统一大市场建设部署，核对企业竞争与落后产能治理、政府采购以及地方招商的要求。","政治理论必刷100题#36":"按2025年《政府工作报告》逐项核对重点领域改革举措，分清统一大市场建设要疏通的环节和要治理的竞争行为。"}},"aspects":[{"title":"低价无序竞争与落后产能退出","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出不正确的表述。A项将会议要求的提升产品品质和推动落后产能有序退出，改为技术改造落后产能、避免淘汰，因此选A。","evidence":"引导企业提升产品品质，推动落后产能有序退出","qids":["政治理论必刷100题#16"]}]},{"title":"市场准入退出与“内卷式”竞争整治","uses":[{"unit":"Q2","role":"直接考查","use":"题目判断2025年重点领域改革举措。③同时列出打通市场准入退出堵点和综合整治“内卷式”竞争，符合当年《政府工作报告》的部署，列入正确组合D。","evidence":"打通市场准入退出等方面制约经济循环的卡点堵点，综合整治“内卷式”竞争","qids":["政治理论必刷100题#36"]}]}],"sources":[{"id":"a8fb7fb9427e00cc","label":"推进全国统一大市场建设","topic":"发展与治理","category":"非时政","text":"2.推进全国统一大市场建设\n《中共中央 国务院关于加快建设全国统一大市场的意见》于 2022 年 4 月 10 日发布。\n《意见》指出，建设全国统一大市场是构建新发展格局的基础支撑和内在要求。《意见》指\n出，加快建设全国统一大市场的工作原则是：立足内需，畅通循环；立破并举，完善制度；\n有效市场，有为政府；系统协同，稳妥推进；主要目标是：持续推动国内市场高效畅通和\n规模拓展，加快营造稳定公平透明可预期的营商环境，进一步降低市场交易成本，促进科\n技创新和产业升级，培育参与国际竞争合作新优势。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#16":{"paper":"政治理论必刷100题","n":16,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",5],"asrc":["国省考政治理论必刷100题.pdf",41],"card":"57575ccba92d0df5a8ded6ea","links":[{"id":"k-89c1d03096d04b0b","role":"直接考查","why":"会议将依法治理低价无序竞争、提升产品品质和推动落后产能有序退出一并列为重点举措。"}]},"政治理论必刷100题#36":{"paper":"政治理论必刷100题","n":36,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",11],"asrc":["国省考政治理论必刷100题.pdf",54],"card":"27e2dd203c7da5889459dadf","links":[{"id":"k-89c1d03096d04b0b","role":"直接考查","why":"报告将打通市场准入退出等方面的堵点与综合整治“内卷式”竞争列入统一大市场建设。"}]}},"terms":{"k-0a6da28c772630a4":{"id":"k-0a6da28c772630a4","mode":"k","type":"概念与词义","title":"全国统一大市场","qs":[],"count":4}},"references":{"market2":{"name":"习近平：纵深推进全国统一大市场建设_中华人民共和国生态环境部","url":"https://www.mee.gov.cn/ywdt/szyw/202509/t20250915_1127508.shtml"}},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-89c1d03096d04b0b":[["政治理论必刷100题#16"],["政治理论必刷100题#36"]]}};
